"""Illustrative sample catalog so the MVP is usable end-to-end.

IMPORTANT: summaries are original text; prices, ratings, durations and hardware tiers are
approximate and for demonstration only. Replace with a licensed source (IGDB / RAWG / store
feeds) via the same ingestion path: sanitise -> build_semantic_doc -> embed. No cover art is
bundled (the UI renders generated gradients) to avoid shipping third-party assets.
"""

# tier scale 1..10 (see app/reco/hardware.py). req = (gpu, cpu, ram_gb, vram_gb, storage_gb)
def G(slug, title, dev, year, price, plats, genres, tags, feats, hours, diff, rating, summary, mn, rc):
    return dict(
        slug=slug, title=title, developer=dev, release_date=f"{year}-01-01", price_cents=price, platforms=plats,
        genres=genres, tags=tags, features=feats, avg_duration_hours=hours, difficulty=diff, rating=rating,
        rating_count=0, summary=summary, description=summary,
        req={"min": dict(zip(("gpu_tier", "cpu_tier", "ram_gb", "vram_gb", "storage_gb"), mn)),
             "rec": dict(zip(("gpu_tier", "cpu_tier", "ram_gb", "vram_gb", "storage_gb"), rc))},
    )

